/***** 画像入れ替え *****/
.thumb-container img {
    max-height: 60px;
    object-fit: cover;
    padding: 5px;
}

#change-image {
    height: 800px;
    width: 800px;
    object-fit: cover;
		display: flex;
}

/***** 左寄せ *******/
.hotwp-fp05-post .hotwp-fp05-post-title{
text-align: left !important;
}

/*** マウスオーバー ***/
.sample-img {
  cursor: pointer;
  max-width:200px;
  position: relative;
  width: 100%;
}
.sample-img img {
  height: auto;
  width: 100%;
}
.hover-mask {
  align-items: center; /* テキストの中央揃え */
  background: rgba(0, 0, 0, .5); /* マスクの色(黒の50%) */
  bottom: 0;
  color: #fff; /* テキストの色 */
  display: flex; /* テキストの中央揃え */
  height: auto;
  justify-content: center; /* テキストの中央揃え */
  left: 0;
  opacity: 0; /* 最初は透明(非表示) */
  position: absolute;
  right: 0;
  top: 0;
  transition: opacity .6s ease; /* ゆっくりopacityのみへ変化させる */
  width: 100%;
}
.hover-mask:hover {
  opacity: 1; /* hoverしたら透過しない(表示させる) */
}
.hover-mask p {
  width: 80%; /* テキストを横幅いっぱいにならないようにする */
}

