function printList(items) {
    if(!items.length) {
        $('#compare_list_html').append('<p class="text">Your cart is empty</p>');
        return false;
    }

    for (var i=0;i<items.length;i++){
        const url = 'https://www.super-flower.com.tw/products-detail/' +items[i].data_blink+'/';
        const imgDisplay = items[i].data_list_pic ? '' : 'hidden';
        $('#compare_list_html').append('<div class="cartItem">'+
        '<div class="Img '+imgDisplay+'"><a href="'+url+'"><img src="'+items[i].data_list_pic+'"></a></div>' +
        '<div class="Txt">'+
            '<p class="title"> <a href="'+url+'">'+items[i].data_title+'</a></p>'+
        '</div>'+
        '<button class="del" style="cursor:pointer" aria-label="Delete"><svg class="icon-garbage"><use xlink:href="#icon-garbage"></use></svg></button>'+
        '</div>');

        const currentItem = items[i];						        

        $('.del').last().on('click', function(){
            compare(currentItem.data_id);
        });
    }
}

