function pdInquiryLen(num) {
    $(".inquiryCartCount").text(num);
    if (num > 0) {
        $('.floatBox .cart[href="#moduleInquiry"]').addClass('show');
    } else {
        $('.floatBox .cart[href="#moduleInquiry"]').removeClass('show');
    }
}

function printInquiryList(items) {
    if(!items.length) {
        $('#car_list_html').append('<p class="text">Your cart is empty</p>');
        return false;
    }

    for (let i=0;i<items.length;i++){
        const url = 'https://www.super-flower.com.tw/products-detail/' +items[i].data_blink+'/';
        const imgDisplay = items[i].data_list_pic ? '' : 'hidden';
        $('#car_list_html').append('<div class="cartItem">'+
        '<div class="Img '+imgDisplay+'"><a href="'+url+'"><img src="'+items[i].data_list_pic+'"></a></div>' +
        '<div class="Txt">'+
            '<p class="title"> <a href="'+url+'">'+items[i].data_title+'</a></p>'+
        '</div>'+
        '<button class="del" aria-label="Delete" style="cursor:pointer"><svg class="icon-garbage"><use xlink:href="#icon-garbage"></use></svg></button>'+
        '</div>');

        const currentItem = items[i];						        

        $('#car_list_html .del').last().on('click', function(){
            addInquiry(currentItem.data_id);
        });
    }
}

function addInquiry(id) 
{
    if(!navigator.cookieEnabled) {
        $('#moduleCookie, .moduleMask').addClass('show');
        return false;
    }

    $.ajax({
        url:'https://www.super-flower.com.tw/inquiry/act/',
        type:"post",
        data:{'index_id':id,'act':5},
        cache:false,
        dataType:"text",
        success:function(result){
            var result = JSON.parse(result);
            if (result.status == 'error')
            {
                alert(result.msg.data_msg);
            }
            else if(result.status == 'add')
            {
                // $('#pr_btn_'+id).text('REMOVE FROM INQUIRY').addClass('bgSecond');
                $('#pr_btn_'+id).addClass('current');

                                    toasts.show('Added to inquiry', 'success');
                            }
            else if(result.status == 'remove')
            {
                // $('#pr_btn_'+id).text('ADD TO INQUIRY').removeClass('bgSecond');
                $('#pr_btn_'+id).removeClass('current');

                                    toasts.show('Removed', 'dark');

            }

            $('#car_list_html').html('');
            if(result.items !== null) 
            {
                printInquiryList(result.items);
                pdInquiryLen(result.items.length);
            }
        }
    });
}

