            window.location.href='https://www.super-flower.com.tw/products/compare/';
        }
    });
})

function pdLen(num) {
    $(".compareCount").text(num);
    if (num > 0) {
        $('.floatBox .cart[href="#moduleCompare"]').addClass('show');
    } else {
        $('.floatBox .cart[href="#moduleCompare"]').removeClass('show');
    }
}

function printList(items) {
    if(!items.length) {
        $('#compare_list_html').append('<p class="text">Your cart is empty</p>');
        return false;
    }

    for (var i=0;i<items.length;i++){
        const url = 'https://www.super-flower.com.tw/products-detail/' +items[i].data_blink+'/';
        const imgDisplay = items[i].data_list_pic ? '' : 'hidden';
        $('#compare_list_html').append('<div class="cartItem">'+
        '<div class="Img '+imgDisplay+'"><a href="'+url+'"><img src="'+items[i].data_list_pic+'"></a></div>' +
        '<div class="Txt">'+
            '<p class="title"> <a href="'+url+'">'+items[i].data_title+'</a></p>'+
        '</div>'+
        '<button class="del" style="cursor:pointer" aria-label="Delete"><svg class="icon-garbage"><use xlink:href="#icon-garbage"></use></svg></button>'+
        '</div>');

        const currentItem = items[i];						        

        $('.del').last().on('click', function(){
            compare(currentItem.data_id);
        });
    }
}

function compare(id)
{
    if(!navigator.cookieEnabled) {
        $('#moduleCookie, .moduleMask').addClass('show');
        return false;
    }

    $.ajax({
        url:'https://www.super-flower.com.tw/products/act/',
        type:"post",
        data:{'index_id':id,'act':5},
        cache:false,
        dataType:"text",
        success:function(result){
            var result = JSON.parse(result);
            if (result.status == 'error')
            {
                alert(result.msg.data_msg);
            }
            else if(result.status == 'add')
            {
                // $('[id="compare_btn_'+id+'"]').text('REMOVE FROM COMPARE').addClass('bgSecond');
                $('[id="compare_btn_'+id+'"]').addClass('current');

                                    toasts.show('Added to compare', 'success');
                            }
            else if(result.status == 'remove')
            {
                // $('[id="compare_btn_'+id+'"]').text('ADD TO COMPARE').removeClass('bgSecond');
                $('[id="compare_btn_'+id+'"]').removeClass('current');

                                    toasts.show('Removed', 'dark');
                            }

            $('#compare_list_html').html('');
            if(result.items !== null) 
            {
                printList(result.items);
                pdLen(result.items.length);
            }
        }
    });
}

function readCompare()
{
    $.ajax({
        url:'https://www.super-flower.com.tw/products/act/',
        type:"post",
        data:{'act':6},
        cache:false,
        dataType:"text",
        success:function(result){
            var result = JSON.parse(result);
            if (result.status && result.status == 'error')
            {
                alert(result.msg.data_msg);
            }

            $('#compare_list_html').html('');
            if(result.items && result.items !== null) 
            {
                printList(result.items);
                pdLen(result.items.length);
            }
        }
    });
}

function removeAllCompare()
{
    $.ajax({
        url:'https://www.super-flower.com.tw/products/act/',
        type:"post",
        data:{'act':7},
        cache:false,
        dataType:"text",
        success:function(result){
            var result = JSON.parse(result);
            if (result.status == 'error')
            {
                alert(result.msg.data_msg);
            }
            else 
            {
                $('[id^="compare_btn_"]').removeClass('current');
            }

            $('#compare_list_html').html('');
            if(result.items !== null) 
            {
                printList(result.items);
                pdLen(result.items.length);
            }
        }
    });
}

function removeCompare(id)
{
    $(`[data-c-id='${id}']`).remove();

    $.ajax({
        url:'https://www.super-flower.com.tw/products/act/',
        type:"post",
        data:{'index_id':id,'act':5},
        cache:false,
        dataType:"text",
        success:function(result){
            var result = JSON.parse(result);
            if (result.status == 'error')
            {
                alert(result.msg.data_msg);
            }

            $('#compare_list_html').html('');
            if(result.items !== null) 
            {
                printList(result.items);
                pdLen(result.items.length);
            }

            if(result.items.length <= 1){
                alert('請加入兩項以上產品進行比較');
                window.location.href='https://www.super-flower.com.tw/products/';
            }
        }
    });
}

(function() {
        const privacyConsent = window.PrivacyConsent;
        if (!privacyConsent) return;

        const codeGroups = {
            functional: {
                head: "\n",
                bodyfront: "\n",
                bodyend: "\n",
            },
            marketing: {
                head: "<!-- Google tag (gtag.js) -->\r\n<script async src=\"https:\/\/www.googletagmanager.com\/gtag\/js?id=G-M113HD0BRJ\" nonce=\"669aa40fac34fc7734ce54c8478106ad\"><\/script>\r\n<script nonce=\"669aa40fac34fc7734ce54c8478106ad\">\r\n  window.dataLayer = window.dataLayer || [];\r\n  function gtag(){dataLayer.push(arguments);}\r\n  gtag('js', new Date());\r\n\r\n  gtag('config', 'G-M113HD0BRJ');\r\n<\/script>\n",
                bodyfront: "\n",
                bodyend: "\n",
            },
        };

        privacyConsent.syncCheckboxes({
            functional: '#cookie_functional',
            marketing: '#cookie_marketing',
        });

        $('#modulePrivacy .topBox .subtitle').on('click', function(e) {
            $(this).parents('.topBox').stop(false, false).toggleClass('open');
            $(this).parents('.topBox').siblings('.text').stop(false, false).slideToggle(300);
        });

        function removePrivacyElement() {
            $('body').removeClass('overflow');
            $('#modulePrivacy, .moduleMask').removeClass('show');
            $('.privacyArea').addClass('check');

            setTimeout(function() {
                $('#modulePrivacy, .privacyArea').remove();
            }, 1000);
        }

        if(navigator.cookieEnabled) {

            $('#modulePrivacy .privacyTrigger, .privacyArea .privacyTrigger').on('click', function(e) {
                e.preventDefault();

                const savedBefore = privacyConsent.get();
                let privacyJson = {
                    necessary: true,
                    functional: true,
                    marketing: true
                };

                if($(this).hasClass('acceptCustom')) {
                    privacyJson = privacyConsent.readCheckboxes({
                        functional: '#cookie_functional',
                        marketing: '#cookie_marketing',
                    });
                }

                const saved = privacyConsent.save(privacyJson);
                if (!saved) return;

                if (savedBefore !== null) {
                    location.reload();
                    return;
                }

                privacyConsent.injectGranted(codeGroups, saved);

                removePrivacyElement();
            });
        } else {
            $('#modulePrivacy .btn a, .privacyArea .btn a.acceptAll').on('click', function(e) {
                e.preventDefault();
                removePrivacyElement();
            });
        }
    })();

